def make_counter(start=0):
    count = start - 1

    def counter():
        nonlocal count
        count += 1
        return count

    return counter


def make_accumulator():
    total = 0

    def accumulate(n):
        nonlocal total
        total += n
        return total

    return accumulate


def make_multiplier(factor):
    def multiply(x):
        return x * factor

    return multiply
